content.text:
{
  "name": "QuTech量子波形发生器",
  "name_en": "QuTech Quantum Waveform Generator",
  "manufacturer": "QuTech",
  "description": "用于量子实验控制的波形发生设备，可生成精确定时的控制信号，并支持数字I/O接口的校准与协议同步，以配合量子测控系统运行。",
  "description_en": "A waveform generation instrument for quantum experiments, used to produce precisely timed control signals and to support digital I/O calibration and protocol synchronization with quantum control electronics.",
  "actions": [
    {
      "action_name": "auto-dio_calibration",
      "description": "执行数字I/O（DIO）接口校准，使设备与外部控制系统的时序和数据对齐。",
      "description_en": "Perform digital I/O (DIO) interface calibration to align timing and data with external control systems."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "自动校准DIO通信协议参数，建立可靠的数字握手与同步配置。",
      "description_en": "Automatically calibrate DIO protocol parameters to establish reliable digital handshaking and synchronization settings."
    },
    {
      "action_name": "auto-output_dio_calibration_data",
      "description": "输出DIO校准数据，供检查、记录或后续配置使用。",
      "description_en": "Output DIO calibration data for inspection, logging, or later configuration use."
    }
  ],
  "tag_hints": [
    "quantum control",
    "waveform generation",
    "DIO calibration",
    "timing synchronization",
    "digital I/O",
    "QuTech"
  ]
}

